#include <bits/stdc++.h>
using namespace std;

string s;
int dp[5000][5000], n;

int main() {
    cin >> n >> s;

    for (int i = 1; i <= n; i++) dp[i][i] = 1;

    for (int len = 2; len <= n; len++) {
        for (int j = 1; j <= n - len + 1; j++) {
            int r = j + len - 1;
            dp[j][r] = 1000000;
            for (int k = j; k < r; k++) {
                dp[j][r] = min(dp[j][r],
                               dp[j][k] + dp[k + 1][r] -
                               static_cast<int>(s[k - 1] == s[r - 1]));
            }
        }
    }

    cout << dp[1][n];
    return 0;
}

